+     */
+    public function directory(Node\Expr\FuncCall $call, Scope $scope): ?string
+    {
+        $argument = $this->calls->argument($call, 0, 'path');
+        $levels = $this->calls->argument($call, 1, 'levels');
+        if ($argument === null) {
+            return null;
+        }
+        $path = $this->resolve($argument, $scope);
+        if ($path === null) {
+            return null;
+        }
+        if ($levels === null) {
